# standalone, pure: no imports, no I/O, no floats; exact integer trial division
def omega(n):
    if n < 1:
        return -1
    c = 0
    x = n
    d = 2
    while d * d <= x:
        if x % d == 0:
            c = c + 1
            while x % d == 0:
                x = x // d
        d = d + 1
    if x > 1:
        c = c + 1
    return c

B = 20
WITNESS = [2, 3, 4, 5, 6, 8, 9, 10, 12, 14, 17, 18, 19, 20]

def holds(n):
    # definitional predicate: for all m < n, m + omega(m) <= n
    m = 1
    while m < n:
        if m + omega(m) > n:
            return False
        m = m + 1
    return True

def verify():
    if B < 2:
        return 'FAIL'
    s = set(WITNESS)
    if len(s) != len(WITNESS):
        return 'FAIL'
    if min(WITNESS) < 2 or max(WITNESS) > B:
        return 'FAIL'
    n = 2
    while n <= B:
        if (n in s) != holds(n):
            return 'FAIL'
        n = n + 1
    for n in WITNESS:
        if holds(n) is not True:
            return 'FAIL'
    return 'PASS'

verify()
